var n=`0469-kofte`;var o=`world-0469`;var r=`TR`;var t=`western-asia`;var a=4;var g=37;var d={en:`Köfte`,ua:`Кефте`};var l={en:`A traditional dish from Türkiye, centered on ground beef, ground lamb, yellow onion, chicken egg. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: яловичий фарш, фарш з ягнятини, жовта цибуля, куряче яйце. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:11,i:[[`ground-beef`,420,`g`],[`ground-lamb`,230,`g`],[`yellow-onion`,160,`g`],[`chicken-egg`,1,`pcs`],[`breadcrumbs`,60,`g`],[`ground-cumin`,5,`g`],[`parsley`,25,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 9 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 9 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:9,i:[]},{en:`Grill over medium-high heat for about 17 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 17 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:17,i:[[`extra-virgin-olive-oil`,30,`ml`]]}];var s={slug:n,id:o,country:`TR`,region:t,servings:4,minutes:37,title:d,text:l,steps:u};export{r as country,s as default,o as id,g as minutes,t as region,a as servings,n as slug,u as steps,l as text,d as title};